import{_ as t,c as e,o as r,ai as o}from"./chunks/framework.B63Sb1io.js";const u=JSON.parse('{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/02/408_CN_12.md","filePath":"post/kaoyan/408/408_CN/02/408_CN_12.md","lastUpdated":1756615767000}'),s={name:"post/kaoyan/408/408_CN/02/408_CN_12.md"};function i(n,a,p,d,l,_){return r(),e("div",null,a[0]||(a[0]=[o('<h1 id="第二章-综述" tabindex="-1">第二章 综述 <a class="header-anchor" href="#第二章-综述" aria-label="Permalink to &quot;第二章 综述&quot;">​</a></h1><h2 id="考纲内容" tabindex="-1">考纲内容 <a class="header-anchor" href="#考纲内容" aria-label="Permalink to &quot;考纲内容&quot;">​</a></h2><p><strong>（一）通信基础</strong></p><div class="suojin"><p>信道、信号、带宽、码元、波特、速率、信源与信宿等基本概念；</p><p>奈奎斯特定理与香农定理；编码与调制；</p><p>电路交换、报文交换与分组交换；数据报与虚电路</p></div><br><p><strong>（二）传输介质</strong></p><div class="suojin"><p>双绞线、同轴电缆、光纤与无线传输介质；物理层接口的特性</p></div><br><p><strong>（三）物理层设备</strong></p><div class="suojin"><p>中继器；集线器</p></div><h2 id="复习提示" tabindex="-1">复习提示 <a class="header-anchor" href="#复习提示" aria-label="Permalink to &quot;复习提示&quot;">​</a></h2><p>物理层考虑的是怎样才能在连接各台计算机的传输介质上传输数据比特流，而不是具体的传输介质。本章概念较多，易出选择题，复习时应抓住重点，如奈奎斯特定理和香农定理的应用、编码与调制技术、物理层接口的特性、物理层设备的功能和特点等。</p>',12)]))}const h=t(s,[["render",i]]);export{u as __pageData,h as default};
